NAME = 'vlsJoNT: Het Nieuwe Testament by Nicolaas De Jonge'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, een apostel van Jezus Christus, naar het gebod van God, onzen Zaligmaker, en van Jezus Christus, onze hope,',
        2: 'aan Timotheüs, mijn oprechten zoon in het geloof: genade, barmhartigheid, vrede zij u, van God den Vader, en van Christus Jezus, onzen Heer.',
        3: 'Doe zooals ik u vermaand heb om in Efesus te blijven, als ik naar Macedonië ging, opdat gij aan sommigen zoudt gebieden geen vreemde leering te leeren,',
        4: 'noch zich bezig te houden met fabelen en eindelooze geslachtlijsten, die meer twistredenen voortbrengen dan opbouwing Gods, die in het geloof is.',
        5: 'Doch het einde van het gebod is liefde uit een zuiver hart en een goede konsciëntie en een ongeveinsd geloof,',
        6: 'waarvan sommigen afgedoold zijn, zich gekeerd hebbende tot ledig geklap,',
        7: 'willende leeraars der wet zijn, niet verstaande, noch wat zij zeggen, noch wat zij bevestigen.',
        8: 'Doch wij weten dat de wet goed is, als iemand ze op wettige manier gebruikt,',
        9: 'dit wetende, dat de wet niet gemaakt is voor een rechtvaardige, maar voor onrechtvaardigen en wederspannigen, voor goddeloozen en zondaars, voor onheiligen en ongoddelijken, voor vadermoorders en moedermoorders, voor doodslagers,',
        10: 'voor hoereerders, voor sodomieters, voor menschendieven, voor leugenaars, voor meineedigen, en al het overige dat strijdt tegen de gezonde leering,',
        11: 'volgens het Evangelie der glorie van den zaligen God, dat mij toevertrouwd is.',
        12: 'Ik dank onzen Heere Jezus Christus, die mij krach t gegeven heeft, dat Hij mij getrouw geacht heeft, stellende mij in de bediening,',
        13: 'mij, die vroeger een lasteraar was, en een vervolger en een verdrukker: maar ik verkreeg barmhartigheid, omdat ik het onwetend deed in ongeloof.',
        14: 'En de genade van onzen Heer was overvloedig met geloof en liefde, die in Christus Jezus is.',
        15: 'Waarachtig is het woord, en waardig aller aanneming, dat Jezus Christus gekomen is tot de wereld om zondaren te behouden, waarvan ik de eerste ben.',
        16: 'Maar daarom verkreeg ik barmhartigheid, opdat Jezus Christus in mij, als den eerste, alle lankmoedigheid zou betoonen, tot een voorbeeld van degenen die gelooven zullen tot het eeuwige leven.',
        17: 'Den Koning nu der eeuwen, den onverderfelijken, onzichtbaren, eenigen God, zij lof en glorie tot in alle eeuwigheid! Amen.',
        18: 'Dit gebod gebied ik u, mijn zoon Timotheüs, naar de profetieën die te voren over u gesproken zijn, dat gij in deze den goeden strijd zult strijden,',
        19: 'behoudende het geloof en een goede konsciëntie, die sommigen verstooten hebbende, schipbreuk hebben geleden in het geloof,',
        20: 'waaronder Hymeneüs en Alexander zijn, die ik aan den Satan heb overgegeven, opdat zij leeren mogen niet te lasteren.',
    },
    2: {
        1: 'Ik vermaan dan, vóór alle dingen, dat er gedaan worden smeekingen, gebeden, voorbiddingen, dankzeggingen, voor alle menschen;',
        2: 'voor koningen en voor allen die in hoogheid zijn, opdat wij een rustig en stil leven mogen leiden, in alle godvruchtigheid en eerbaarheid.',
        3: 'Want dat is goed en aangenaam voor het aangezicht van God, onzen Zaligmaker,',
        4: 'die wil dat alle menschen behouden worden en komen tot kennis der waarheid.',
        5: 'Want er is één God, ook één Middelaar tusschen God en menschen, die zelf mensch is, Christus Jezus,',
        6: 'die zich zelven gegeven heeft tot een losprijs voor allen, het getuigenis ter geschikter tijd,',
        7: 'waartoe ik gesteld ben als prediker en apostel, (ik spreek waarheid, ik lieg niet!) als leer aar der heidenen in geloof en waarheid.',
        8: 'Ik wil dan dat de mannen bidden in alle plaats, opheffende heilige handen, zonder gramschap en twisting.',
        9: 'Evenzoo dat ook de vrouwen in een zedig gewaad, met schaamte en ingetogenheid, zich zelven versieren, niet met haarvlechten en goud, of paarlen, of kostbare kleeding,',
        10: 'maar— gelijk het aan vrouwen betaamt die belijden God te vreezen— door goede werken.',
        11: 'Een vrouw moet zich laten onderwijzen in stilheid, in alle onderdanigheid.',
        12: 'Doch ik laat aan een vrouw niet toe om onderwijs te geven, noch om over den man te heerschen maar om in stilheid te zijn.',
        13: 'Want Adam is eerst gevormd, daarna Eva.',
        14: 'En Adam is niet verleid, maar de vrouw, verleid zijnde, is in overtreding geweest;',
        15: 'doch zij zal behouden worden door kinderen te baren, als zij blijven in geloof en liefde en heiligheid, met ingetogenheid.',
    },
    3: {
        1: 'Waasachtig is het gezegde: als iemand de bediening van een opziener zoekt, dan begeert hij een goed werk.',
        2: 'Daarom moet de opziener onberispelijk zijn, de man van één vrouw, matig, ingetogen, eerbaar, genegen tot herbergzaamheid, bekwaam tot onderwijs,',
        3: 'niet genegen tot wijn, geen twister, maar zedig, vreedzaam, niet geldzuchtig,',
        4: 'die zijn eigen huisgezin goed bestiert, zijn kinderen in onderdanigheid houdende met alle eerbaarheid;',
        5: '— want als iemand zijn eigen huisgezin niet weet te bestieren, hoe zal hij zorgdragen voor de gemeente Gods?',
        6: 'geen nieuweling, opdat hij niet valle in het oordeel des duivels, door hoovaardigheid.',
        7: 'Hij moet ook een goed getuigenis hebben van degenen die buiten de gemeente zijn, opdat hij niet valle tot verachting en in een strik des duivels.',
        8: 'De diakenen insgelijks moet eerbaar zijn, niet dubbel van tong, niet genegen tot veel wijn, geen vuil gewin zoekers,',
        9: 'hebbende de verborgenheid des geloofs in een zuivere konsciëntie.',
        10: 'En dezen moeten ook eerst op de proef gesteld worden en daarna mogen zij dienen als diakenen als zij onberispelijk zijn.',
        11: 'De vrouwen insgelijks moeten eerbaar zijn, geen lasteressen, matig, getrouw in alles.',
        12: 'Diakens moeten aangesteld worden die mannen zijn van één vrouw, hun kinderen en hun eigen huisgezinnen goed bestieren.',
        13: 'Want die goed zullen gediend hebben als diakenen, die zullen voor zich zelven een goeden opgang verkrijgen en veel vrijmoedigheid in het geloof dat in Christus Jezus is.',
        14: 'Dit schrijf ik u, hopende haast tot u te komen;',
        15: 'doch als ik vertoef, opdat gij weten moogt hoe gij u moet gedragen in het huis Gods, dat is de gemeente van den levenden God, de pilaar en steun van de waarheid.',
        16: 'En buiten twijfel, groot is de verborgenheid der godvruchtigheid! Die geopenbaard is in het vleesch, is gerechtvaardigd in den geest, is verschenen aan de engelen, is gepredikt onder de heidenen, is geloofd in de wereld, is opgenomen in glorie!',
    },
    4: {
        1: 'Doch de Geest zegt duidelijk dat er in de laatste tijden sommigen zullen afvallen van liet geloof, luisterende naar verleidende geesten en naar leeringen der booze geesten,',
        2: 'in geveinsdheid der leugensprekers, hun eigene konscientië toegebrand hebbende,',
        3: 'verbiedende te trouwen, ca gebiedende zich te onthouden van spijzen die God geschapen heeft om met dankzegging gebruikt te worden door de geloovigen en die de waarheid hebben bekend.',
        4: 'Want alle schepsel Gods is goed, en niets is er verwerpelijk, genomen zijnde met dankzegging,',
        5: 'want het wordt geheiligd door Gods woord en door gebed.',
        6: 'Deze dingen den broederen voorstellende zult gij een goed dienaar van Jezus Christus zijn, opgevoed met de woorden des geloofs en der goede leering die gij gevolgd hebt.',
        7: 'Doch verwerp de ongoddelijke en oudwijfsche fabelen, en oefen u zelven tot godvruchtigheid,',
        8: 'want de lichamelijke oefening is tot weinig voordeelig, maar de godvruchtigheid is tot alles voordeelig, hebbende een belofte voor het tegenwoordige en het toekomende leven.',
        9: 'Waarachtig is het woord en waardig aller aanneming.',
        10: 'Want tot dien einde arbeiden wij en strijden wij, omdat wij hebben gehoopt op den levenden God, die een behouder is van alle menschen, doch het meest van de geloovigen.',
        11: 'Verkondig en onderwijs deze dingen.',
        12: 'Dat niemand uw jonkheid verachte, maar zijt een voorbeeld der geloovigen in woord, in levensmanier, in liefde, in vertrouwen, in reinheid.',
        13: 'Houd aan met het lezen, met liet vermanen, met liet onderwijzen totdat ik kom.',
        14: 'Verzuim niet de genadegave die in u is, die u gegeven is door profetie met oplegging der handen van het ouderlingschap.',
        15: 'Bedenk deze dingen, maak er werk van, opdat uw vooruitgang openbaar zij aan allen.',
        16: 'Let op u zelven en op het onderwijs; volhard in deze dingen; want dit doende zult gij u zelven behouden en degenen die u hooren.',
    },
    5: {
        1: 'Bestraf een ouden man niet scherpelijk, maar vermaan hem als een vader; de jonge mannen als broeders;',
        2: 'oude vrouwen als moeders, jonge vrouwen als zusters in alle reinheid.',
        3: 'Acht de weduwen die waarlijk weduwen zijn.',
        4: 'Doch als een weduwe kinderen heeft, of kindskinderen, laat die dan leeren eerst hun eigen huisgezin godvruchtig te verzorgen en wedervergelding te bewijzen aan de ouders; want dat is aangenaam voor Gods aangezicht.',
        5: 'Doch die waarlijk weduwe is en alleen gelaten, die moet op God hopen en volharden in smeekingen en gebeden nacht en dag.',
        6: 'Maar die wellustig leeft die is levende dood.',
        7: 'Beveel dan deze dingen opdat zij onberispelijk mogen zijn.',
        8: 'Doch als iemand niet zorgt voor de zijnen, en vooral voor zijn huisgenoot ten, die heeft het geloof verloochend en is erger dan een ongeloovige.',
        9: 'Laat er geen weduwe gekozen worden tot verzorgster die minder dan zestig jaar oud is, en alleen die de vrouw van één man is geweest,',
        10: 'die een goed getuigenis heeft in goede werken; als zij kinderen opgevoed heeft, als zij vreemdelingen geherbergd heeft, als zij de voeten van heiligen gewasschen heeft, als zij hulp bewezen heeft aan verdrukten, als zij allerlei goed werk nagevolgd heeft.',
        11: 'Doch jongere weduwen moet gij weigeren als verzorgsters, want als zij door wellustigheid afgevoerd zijn van Christus dan willen zij trouwen,',
        12: 'schuldig zijnde omdat zij haar eerste trouw geschonden hebben.',
        13: 'Daarenboven leeren zij ook ledig te zijn, bij de huizen omloopende, en niet al leen ledig maar ook klapachtig en bemoeizuchtig, sprekende hetgeen niet betaamt.',
        14: 'Ik wil dan dat jongere weduwen trouwen, kinderen voortbrengen, het huisgezin waarnemen, geen oorzaak geven aan de tegenpartij om te lasteren.',
        15: 'Want sommigen zijn alreeds afgeweken achter den Satan.',
        16: 'Als eenige geloovige, hetzij man of vrouw, weduwen heeft in zijn familie, dat hij die verzorge, en dat de gemeente niet bezwaard worde, opdat zij genoeg moge hebben voor degenen die waarlijk weduwen zijn.',
        17: 'Voor de ouderlingen, die goed besturen, moet men dubbele achting hebben, vooral voor degenen die arbeiden in het woord en in het onderwijs.',
        18: 'Want de Schriftuur zegt: een os die den dorschvloer treedt zult gij niet muilbanden en de werkman is zijn loon waardig.',
        19: 'Tegen een ouderling zult gij geen beschuldiging opnemen, dan alleen onder twee of drie getuigen.',
        20: 'Degenen die zondigen, moet gij bestraffen voor het aangezicht van allen, opdat ook de overigen mogen vreezen.',
        21: 'Ik betuig voor het aangezicht van God en van Christus Jezus en van de uitverkoren engelen, dat gij deze dingen onderhoudt, zonder vooringenomenheid, niets doende naar voorliefde.',
        22: 'Leg aan niemand haastelijk de handen op, en heb geen gemeenschap met de zonden van anderen. Bewaar u zelven rein.',
        23: 'Drink niet langer water, maar gebruik een weinig wijn, om uw maag en om uw menigvuldige zwakheden.',
        24: 'De zonden van sommige menschen zijn vooraf openbaar, eer men ze onderzoekt, doch die van anderen komen daarna te voorschijn.',
        25: 'Desgelijks ook zijn de goede werken vooraf openbaar, en die het niet zijn die kunnen niet verborgen blijven.',
    },
    6: {
        1: 'zoovelen als er dienstbaren zijn onder het juk moeten hun eigen meesters allen eerbied waardig achten, opdat de Naam van God en de leering niet gelasterd worden moge.',
        2: 'En die geloovige meesters hebben mogen dezen niet minachten omdat zij broeders zijn, maar zij moeten hen te meer dienen omdat zij geloovig en bemind zijn, als zijnde mededeelgenooten derzelfde weldaad. Onderwijs deze dingen en vermaan hen.',
        3: 'Als iemand wat anders onderwijst en zich niet voegt naar de gezonde woorden van onzen Heere Jezus Christus, en naar het onderwijs dat naar de godvruchtigheid is,',
        4: 'die is opgeblazen, niets wetende, maar razende over vraagstukken en redeneeringen, waaruit nijdigheid voortkomt, twist, lasteringen, kwade bedenkingen,',
        5: 'krakeelingen van menschen die verdorven zijn van zin en van de waarheid beroofd, meenende dat de godvruchtigheid een gewin is.',
        6: 'En de godvruchtigheid is een groot gewin met vergenoegdheid.',
        7: 'Want wij hebben niets in de wereld gebracht en het is zeker dat wij er ook niets kunnen uitdragen.',
        8: 'Maar voedsel hebbende en deksel, zullen wij daarmede tevreden zijn.',
        9: 'Doch die willen rijk worden vallen in bekoring en in een strik en in vele dwaze en schadelijke begeerlijkheden, die de menschen doen zinken tot verderf en ondergang,',
        10: 'want een wortel van alle kwaad is de gierigheid, waartoe sommigen zich begevende zijn afgedwaald van het geloof en zich zelven met vele smarten hebben doorstoken.',
        11: 'Maar gij, o mensch Gods! vlied deze dingen, en tracht naar rechtvaardigheid, godvruchtigheid, geloof, liefde, volharding, zachtmoedigheid.',
        12: 'Strijd den goeden strijd des geloofs, grijp naar het eeuwige leven, waartoe gij geroepen zijt en de goede belijdenis beleden hebt voor het aangezicht van veel getuigen.',
        13: 'Ik gebied u voor het aangezicht van God die alle dingen leven doet en van Christus Jezus die de goede belijdenis voor Pontius Pilatus beleden heeft,',
        14: 'dat gij het gebod onbevlekt, onberispelijk bewaart tot op de verschijning van onzen Heere Jezus Christus,',
        15: 'die Hij ter rechter tijd vertoonen zal, Hij de zalige en alleen machtige, de Koning dergenen die als koningen heerschen en de Heer dergenen die als heeren gebieden,',
        16: 'die alleen onsterfelijkheid bezit, een ongenaakbaar licht bewonende, dien geen mensch gezien heeft, noch zien kan; aan wien de eere toekomt en eeuwige kracht! Amen.',
        17: 'Aan de rijken in de tegenwoordige eeuw moet gij gebieden niet hoogmoedig te zijn, noch te vertrouwen op de ongestadigheid van den rijkdom, maar op den God die leeft en die ons alle dingen overvloediglijk verschaft tot gebruik;',
        18: 'om weldadig te zijn, rijk te zijn in goede werken, gewillig te zijn tot uitdeelen, gemeenzaam te zijn,',
        19: 'voor zich zelven een goeden grond bijeen verzamelende tot de toekomst, opdat zij het waarachtige leven mogen bekomen.',
        20: 'O Timotheüs! bewaar wat u is toebetrouwd, u afkeerende van het ledig geklap en van de tegenspraak der zoogenaamde wetenschap,',
        21: 'die sommigen uitbazuinende, van het geloof zijn afgedoold. De genade zij met u! Amen.',
    },
}
